/* Session 9 drills (serverless, events, integration & analytics). stub values must match SESSION.stub chip labels
   exactly ('any' accepts anything). words must appear verbatim (case-insensitive) in q so they can be highlighted
   after submit.
   E1 (Exam Q1, tag C), E2 (Exam Q50, tag K), E3 (Exam Q57, tag K — the EMR half; Session 8 B2 keeps the Redshift
   half) and E4 (Exam Q40, tag F) come from his baseline misses, reconstructed from the one-line summaries in
   CONTEXT §3. E5–E6 carry his prestige-distractor pattern (src 'Exam pattern', tag C): Global Accelerator and
   Transit Gateway offered for a queue problem (E5), Lake Formation for a query problem with no governance need (E6).
   Options are written to the same size; each distractor breaks on one stated detail. Stub slots record what the stem
   literally states ('any' / 'none stated' when it states nothing for that slot). No correct answer depends on a
   change after the exam guide except E19 (Kinesis Data Analytics for SQL retired; see its expl and update). E2 and E30
   mention that Data Pipeline is closed to new customers, but Glue wins on least operational overhead either way. */
(function () {
  'use strict';
  const S = window.SESSION = window.SESSION || {};
  const _o = (t, ok, why) => ({ t, ok: !!ok, why });
  S.drills = [
    /* ---------------- his record ---------------- */
    { id: 'E1', src: 'Exam Q1', line: 'firehose', mine: true, tag: 'C',
      q: 'A media company collects clickstream events from its website at about 5,000 events per second. The events must be stored in Amazon S3 within 5 minutes for later analysis with Amazon Athena. Nobody reads the events in real time. The solution must have the LEAST operational overhead.',
      opts: [_o('Send the events to an Amazon Data Firehose stream with an Amazon S3 destination and a buffer interval of 300 seconds or less.', 1, 'Firehose was built for this: it buffers the stream and writes it to S3 with no code, no shards and no servers.'),
        _o('Send the events to a Kinesis data stream, and have an AWS Lambda function read each batch and write it to Amazon S3 as objects.', 0, 'Your baseline pick. It works, but you write, size and retry the function — Firehose does the same delivery as configuration.'),
        _o('Send the events to an Amazon SQS queue, and run a fleet of EC2 instances that poll the queue and upload files to Amazon S3.', 0, 'Servers to patch and scale for a delivery job — fails least operational overhead.'),
        _o('Send the events to a Kinesis data stream, and register Amazon Athena as an enhanced fan-out consumer that reads the records.', 0, 'Athena queries files in S3; it is not a stream consumer, so nothing would ever reach S3.')],
      stub: { pat: 'stream', del: 'none stated', lat: 'near real time', sup: 'least ops' }, words: ['stored in Amazon S3 within 5 minutes', 'Nobody reads the events in real time', 'LEAST operational overhead'],
      expl: 'Your baseline **Q1**, tag C. A stream that only has to **land in S3**, minutes allowed, least ops = **Firehose**. A Lambda consumer is the look-alike: it works, but it is code you own.' },
    { id: 'E2', src: 'Exam Q50', line: 'etl', mine: true, tag: 'K',
      q: 'Every night, partner systems drop about 200 GB of CSV files into an Amazon S3 bucket. A data team must convert the new files to Apache Parquet, partition them by date, and make them queryable in Amazon Athena. The team has no cluster experience and wants the solution with the LEAST operational overhead.',
      opts: [_o('Launch an Amazon EMR cluster on EC2 each night, run a Spark step that writes partitioned Parquet, then terminate the cluster.', 0, 'Works, but you size, configure and troubleshoot a cluster every night — fails least operational overhead (your Q50 detour).'),
        _o('Schedule an AWS Data Pipeline that starts an EC2 instance each night to convert the files to Parquet and update the catalog.', 0, 'Data Pipeline is closed to new customers, and the EC2 resource and script are yours to manage.'),
        _o('Run an AWS Glue crawler and a scheduled AWS Glue ETL job with job bookmarks that writes partitioned Parquet back to Amazon S3.', 1, 'Serverless ETL: the crawler fills the Data Catalog for Athena, bookmarks read only the new files, nothing to size or patch.'),
        _o('Load the CSV files into Amazon Redshift each night with the COPY command, then UNLOAD them to Amazon S3 as partitioned Parquet.', 0, 'A warehouse run every night just to change a file format — more to operate and pay for than serverless ETL.')],
      stub: { pat: 'ETL', del: 'none stated', lat: 'batch', sup: 'least ops' }, words: ['convert the new files to Apache Parquet', 'no cluster experience', 'LEAST operational overhead'],
      expl: 'Your baseline **Q50**, tag K: the keyword decides it. ETL + **least operational overhead** = **Glue** (crawler, Data Catalog, serverless job, bookmarks). EMR is the same work with a cluster to run.' },
    { id: 'E3', src: 'Exam Q57', line: 'etl', mine: true, tag: 'K',
      q: 'A company runs an on-premises Hadoop cluster with Apache Spark and Apache Hive jobs over 400 TB of data. It will move the data to Amazon S3 and must run the existing big data jobs with as few code changes as possible. The jobs run for 4 hours every night. The solution must be the MOST cost-effective.',
      opts: [_o('Run the jobs on a long-running Amazon EMR cluster that reads Amazon S3, with every node On-Demand all day and all night.', 0, 'No code change, but it pays for a cluster that sits idle 20 hours a day.'),
        _o('Run the jobs on a transient Amazon EMR cluster that reads Amazon S3, with On-Demand core nodes and Spot task nodes.', 1, 'Same Spark and Hive code, a cluster that exists only for the run, and Spot where an interruption costs only time.'),
        _o('Run the jobs on a transient Amazon EMR cluster with HDFS on Spot core nodes, keeping only the primary node On-Demand.', 0, 'A Spot interruption on a core node can lose HDFS data mid-job; AWS keeps core nodes On-Demand.'),
        _o('Rewrite the Hive jobs as Amazon Athena queries and the Spark jobs as AWS Lambda functions started every night.', 0, 'A rewrite of everything, and 4-hour Spark jobs do not fit Lambda’s 15-minute limit.')],
      stub: { pat: 'ETL', del: 'none stated', lat: 'batch', sup: 'cheapest' }, words: ['Apache Spark and Apache Hive', 'existing big data jobs', 'as few code changes as possible', 'MOST cost-effective'],
      expl: 'Your baseline **Q57**, the processing half, tag K: **big data** + Spark/Hive = **EMR**. Cheapest = a **transient** cluster with **Spot task nodes** and On-Demand core nodes. The SQL/BI half (Redshift) is Session 8 drill B2.' },
    { id: 'E4', src: 'Exam Q40', line: 'sfn', mine: true, tag: 'F',
      q: 'A company is building a new order-fulfilment application from several AWS Lambda functions. Orders above a set value must wait for a manager’s approval, which can take up to 3 days. Every step needs retries, and the team must be able to see where each order is. The solution must need the LEAST operational overhead.',
      opts: [_o('Build an AWS Step Functions Express workflow that calls the functions and pauses on a .waitForTaskToken task for the approval.', 0, 'Express workflows stop at 5 minutes and do not support .waitForTaskToken.'),
        _o('Build an Amazon SWF workflow with a decider and activity workers on Amazon EC2 that poll for tasks and the manager’s decision.', 0, 'The older service: deciders and workers you write and run on servers. AWS recommends Step Functions for new applications — your Q40.'),
        _o('Chain the functions through Amazon SQS queues and store each order’s current step and approval state in an Amazon DynamoDB table.', 0, 'It can work, but you build the state tracking, retries and timeouts yourself.'),
        _o('Build an AWS Step Functions Standard workflow that calls the functions and pauses on a .waitForTaskToken task for the approval.', 1, 'Standard runs up to a year, retries every step, shows each execution’s history and waits on a task token for the manager.')],
      stub: { pat: 'workflow', del: 'none stated', lat: 'any', sup: 'least ops' }, words: ['manager’s approval', 'up to 3 days', 'see where each order is', 'LEAST operational overhead'],
      expl: 'Your baseline **Q40**, tag F. Steps + retries + a wait of days for a person = **Step Functions Standard** with a callback task. Express cannot wait; **SWF** still exists but is the legacy answer for new workflows.' },
    { id: 'E5', src: 'Exam pattern', line: 'sqs', mine: true, tag: 'C',
      q: 'An e-commerce application in one AWS Region has a web tier that accepts orders and a processing tier of Amazon EC2 instances in an Auto Scaling group. During flash sales the processing tier is overwhelmed and orders are lost. The company wants the MOST cost-effective way to make sure every order is processed.',
      opts: [_o('Put AWS Global Accelerator in front of a Network Load Balancer for the processing tier so orders reach it over the AWS network.', 0, 'Prestige distractor: it speeds up network paths to endpoints. Nothing holds the orders, so spikes still drop them.'),
        _o('Have the web tier send each order to an Amazon SQS queue, and scale the processing tier on the number of messages waiting.', 1, 'The queue absorbs the spike; workers scale on the backlog and take each order when they can.'),
        _o('Connect the web tier and processing tier subnets through AWS Transit Gateway, and scale the processing tier on CPU usage.', 0, 'Prestige distractor: the tiers already share a Region and network. Transit Gateway routes traffic; it holds no orders.'),
        _o('Have the web tier publish each order to an Amazon SNS topic, and subscribe the processing tier’s HTTP endpoint to the topic.', 0, 'A standard SNS topic pushes and retries, but stores nothing while the tier is overloaded — orders can still be lost.')],
      stub: { pat: 'queue', del: 'at least once', lat: 'any', sup: 'cheapest' }, words: ['in one AWS Region', 'orders are lost', 'MOST cost-effective', 'every order is processed'],
      expl: 'Your prestige pattern, integration edition. Lost work under spikes = no **buffer**. **SQS** + scaling on queue depth is built for it; Global Accelerator and Transit Gateway answer network problems this scenario does not have.' },
    { id: 'E6', src: 'Exam pattern', line: 'query', mine: true, tag: 'C',
      q: 'A security team stores one year of AWS CloudTrail logs in Amazon S3 as compressed JSON. A few times a month, engineers run SQL queries over the logs during investigations. There is no requirement to restrict access below the bucket level. The company wants the MOST cost-effective solution.',
      opts: [_o('Register the bucket in AWS Lake Formation, add LF-tags and column grants, and query the logs from an Amazon Redshift cluster.', 0, 'Prestige distractor: governance nobody asked for, plus a warehouse running all month for a few queries.'),
        _o('Load the logs into a provisioned Amazon Redshift cluster every night, and let the engineers query the cluster when needed.', 0, 'A cluster billed every hour of the month for a few queries.'),
        _o('Define a table over the log prefix in the AWS Glue Data Catalog, and query the logs in place with Amazon Athena when needed.', 1, 'Serverless SQL on S3: pay only for the data each investigation scans, nothing in between.'),
        _o('Stream the logs into Amazon OpenSearch Service through Amazon Data Firehose, and keep the domain running for investigations.', 0, 'A domain running all month and a second copy of the logs — not the most cost-effective.')],
      stub: { pat: 'ad hoc query', del: 'none stated', lat: 'batch', sup: 'cheapest' }, words: ['A few times a month', 'no requirement to restrict access', 'MOST cost-effective'],
      expl: 'Occasional SQL on files already in S3 = **Athena** (pay per TB scanned). **Lake Formation** is a real service built for fine-grained governance — the stem rules that out, so it is the prestige option here.' },

    /* ---------------- SQS / SNS ---------------- */
    { id: 'E7', src: 'New', line: 'sqs',
      q: 'An application processes messages from an Amazon SQS standard queue with Amazon EC2 workers. Each message takes about 2 minutes to process. Many messages are processed twice, although no worker fails. The queue uses default settings. Which change fixes the problem with the LEAST effort?',
      opts: [_o('Convert the queue to an SQS FIFO queue with content-based deduplication, so that every message is received only once.', 0, 'FIFO deduplicates sends; a message whose visibility timeout expires is still delivered again — and a new queue is more effort.'),
        _o('Enable long polling with a 20-second wait time on the queue, so that the workers make fewer receive calls in total.', 0, 'Long polling reduces empty receives; it does not keep an in-flight message hidden for longer.'),
        _o('Configure a dead-letter queue with a maxReceiveCount of 1, so that a message received twice moves to that queue.', 0, 'Messages still being processed would be moved to the DLQ — the duplicates become lost work.'),
        _o('Raise the queue’s visibility timeout above the 2-minute processing time, so that a message stays hidden until deleted.', 1, 'The default 30 s expires mid-processing and the message reappears; a longer timeout stops it.')],
      stub: { pat: 'queue', del: 'none stated', lat: 'any', sup: 'least ops' }, words: ['about 2 minutes', 'processed twice', 'no worker fails', 'default settings'],
      expl: 'Default visibility timeout = **30 s**; processing = 2 minutes. The message becomes visible again while the first worker is busy. Set the timeout above the processing time (or extend it from the worker).' },
    { id: 'E8', src: 'New', line: 'sqs',
      q: 'A bank sends account transactions to an Amazon SQS queue. Transactions for the same account must be processed in the order they were sent and must never be applied twice, while different accounts must be processed in parallel by several consumers. Which queue configuration meets these requirements?',
      opts: [_o('An SQS FIFO queue with the account ID as the message group ID and a deduplication ID set on every transaction.', 1, 'Order per group, deduplication within 5 minutes, and different accounts (groups) processed in parallel.'),
        _o('An SQS FIFO queue with one fixed message group ID for all transactions and content-based deduplication turned on.', 0, 'Order and no duplicates, but one group means one message at a time — no parallelism across accounts.'),
        _o('An SQS standard queue with the account ID as the message group ID, so that fair queues keep each account in order.', 0, 'Fair queues limit noisy tenants; a standard queue is still best-effort ordered and at least once.'),
        _o('An SQS standard queue with long polling, and consumers that sort every batch by timestamp before applying it.', 0, 'A batch from a standard queue can miss earlier messages or repeat one; sorting cannot fix that.')],
      stub: { pat: 'queue', del: 'ordered', lat: 'any', sup: 'none stated' }, words: ['in the order they were sent', 'never be applied twice', 'different accounts must be processed in parallel'],
      expl: 'Order per key + no duplicates = **FIFO**; parallel across keys = **message group ID per account**. One group serialises everything; a standard queue (fair queues included) does not order.' },
    { id: 'E9', src: 'New', line: 'sns',
      q: 'A retailer publishes every new order to an existing Amazon SNS topic. Three teams — inventory, billing and analytics — must each process every order. The analytics service is sometimes offline for several hours and must catch up without losing orders. The solution must require the LEAST change to the publisher.',
      opts: [_o('Subscribe one shared Amazon SQS queue to the topic, and have all three teams’ services poll their messages from it.', 0, 'Competing consumers split the orders; each team would see only part of them.'),
        _o('Subscribe each team’s HTTPS endpoint directly to the topic, and rely on SNS delivery retries while analytics is offline.', 0, 'A standard topic retries for a limited time and stores nothing for hours; analytics can still lose orders.'),
        _o('Subscribe one Amazon SQS queue per team to the existing topic, and have each team’s service poll only its own queue.', 1, 'Fan-out: SNS copies each order to three queues; each queue holds its team’s copy until it is processed.'),
        _o('Replace the topic with an Amazon EventBridge custom bus, and add one rule per team with an SQS queue as its target.', 0, 'It would work, but the publisher must change from SNS to EventBridge — fails least change to the publisher.')],
      stub: { pat: 'fan-out', del: 'none stated', lat: 'any', sup: 'least ops' }, words: ['existing Amazon SNS topic', 'each process every order', 'offline for several hours', 'LEAST change to the publisher'],
      expl: 'Every team gets every order + one team falls behind for hours = **SNS → one SQS queue per subscriber**. One shared queue splits the orders; a standard SNS topic alone keeps nothing for a subscriber that is away.' },
    { id: 'E10', src: 'New', line: 'sqs',
      q: 'A fleet of 40 worker processes polls an Amazon SQS queue that receives only a few messages each minute. The SQS bill shows millions of ReceiveMessage requests that return no messages. The company wants to reduce this cost with the LEAST change to the workers.',
      opts: [_o('Set the queue’s delivery delay to 15 minutes, so that messages are collected and returned to the workers in larger groups.', 0, 'A delay postpones every message; the empty receives continue.'),
        _o('Set the queue’s receive message wait time to 20 seconds, so that every ReceiveMessage call uses long polling.', 1, 'Long polling waits up to 20 s for a message before answering: far fewer empty, billed responses, with no worker change.'),
        _o('Set the queue’s visibility timeout to 12 hours, so that the workers stop receiving the same messages over and over.', 0, 'Visibility controls duplicates of in-flight messages, not empty receives.'),
        _o('Convert the queue to an SQS FIFO queue, so that the workers receive messages in batches of 10 instead of one at a time.', 0, 'Batches of 10 exist on both queue types; empty responses remain, and a new queue means changing the workers.')],
      stub: { pat: 'queue', del: 'none stated', lat: 'any', sup: 'cheapest' }, words: ['return no messages', 'reduce this cost', 'LEAST change to the workers'],
      expl: 'Empty receives = **short polling**. Set the queue’s **receive message wait time** (long polling, up to **20 s**). Delays, visibility and FIFO solve other problems.' },

    /* ---------------- EventBridge ---------------- */
    { id: 'E11', src: 'New', line: 'eb',
      q: 'An operations team wants to run an AWS Lambda cleanup function and email the eight on-call engineers whenever any Amazon EC2 instance in the account is terminated. The solution must react within seconds and need the LEAST operational overhead.',
      opts: [_o('Create an AWS Config rule that evaluates the instances every 24 hours and invokes the function and an SNS topic for changes.', 0, 'A periodic evaluation reacts up to a day late — fails within seconds.'),
        _o('Create an Amazon EventBridge rule on the default event bus that matches the terminated state and targets the function and SNS.', 1, 'EC2 state changes arrive on the default bus by themselves; one rule, two targets, seconds.'),
        _o('Schedule a Lambda function every minute that calls DescribeInstances, compares the results, and invokes the cleanup function and SNS.', 0, 'Polling code to write and run for events that EventBridge already delivers — fails least ops.'),
        _o('Create an Amazon EventBridge rule on the default event bus that targets the function and one SNS topic per on-call engineer.', 0, 'Nine targets on one rule: targets per rule are fixed at 5. One SNS topic with eight email subscriptions is one target.')],
      stub: { pat: 'event routing', del: 'none stated', lat: 'real time', sup: 'least ops' }, words: ['whenever any Amazon EC2 instance in the account is terminated', 'within seconds', 'LEAST operational overhead'],
      expl: 'AWS service state change + react = **EventBridge rule on the default bus**. A rule takes at most **5 targets** (fixed), so the eight engineers sit behind one SNS topic. Config evaluates compliance, and polling rebuilds what the bus already does.' },
    { id: 'E12', src: 'New', line: 'eb',
      q: 'A company uses a SaaS help-desk application that is an Amazon EventBridge partner. Every new high-priority ticket must start an AWS Step Functions workflow, and low-priority tickets must go to an Amazon SQS queue. The company wants the LEAST operational overhead and no public endpoint to maintain.',
      opts: [_o('Host an Amazon API Gateway webhook with an AWS Lambda function that parses each ticket and starts the workflow or sends it to the SQS queue.', 0, 'A public endpoint and parsing code — the stem rules out both.'),
        _o('Run a scheduled Lambda function that polls the SaaS API every minute for new tickets and routes them by priority to each target.', 0, 'Polling code, API rate limits and up to a minute of delay — more to run than a partner event source.'),
        _o('Set up the partner event source, associate it with a partner event bus, and add one rule that sends every ticket to both targets.', 0, 'No content routing: low-priority tickets would start workflows and high-priority ones would land in the queue.'),
        _o('Set up the partner event source, associate it with a partner event bus, and add two rules whose patterns match the ticket priority.', 1, 'Partner events arrive with no endpoint to host; each rule routes one priority to its target.')],
      stub: { pat: 'event routing', del: 'none stated', lat: 'any', sup: 'least ops' }, words: ['EventBridge partner', 'high-priority ticket', 'no public endpoint to maintain', 'LEAST operational overhead'],
      expl: 'SaaS events = **partner event source → partner event bus**; routing by a field in the event = **one rule per pattern**. Webhooks and pollers rebuild what EventBridge offers as configuration.' },
    { id: 'E13', src: 'New', line: 'eb',
      q: 'A subscription platform must send a reminder 14 days after each customer signs up, at 09:00 in the customer’s own time zone. About 2 million customers sign up each year, and each reminder invokes an AWS Lambda function once. The solution must need the LEAST operational overhead.',
      opts: [_o('Create one EventBridge Scheduler schedule per customer with an at() expression, the customer’s time zone and the function.', 1, 'Scheduler is built for many one-time schedules, each in its own time zone, invoking a target directly.'),
        _o('Create an Amazon EventBridge rule with a cron expression per customer on a custom event bus, each with the function as target.', 0, 'Scheduled rules run only on the default bus, and rules default to 300 per bus; per-customer rules are the wrong tool at this scale.'),
        _o('Run a cron job on an Amazon EC2 instance every minute that queries a database for due reminders and invokes the function.', 0, 'A server, a schedule table and polling code to run — fails least operational overhead.'),
        _o('Start an AWS Step Functions Express workflow for each customer that waits 14 days in a Wait state, then invokes the function.', 0, 'Express workflows stop at 5 minutes; they cannot wait 14 days.')],
      stub: { pat: 'event routing', del: 'none stated', lat: 'any', sup: 'least ops' }, words: ['14 days after each customer signs up', 'own time zone', '2 million customers', 'LEAST operational overhead'],
      expl: 'Time as the trigger, millions of one-off schedules, local time zones = **EventBridge Scheduler** (`at()` + time zone). Rules default to 300 per bus; Express waits at most 5 minutes.' },
    { id: 'E14', src: 'New', line: 'eb',
      q: 'New items in an Amazon DynamoDB table must start an AWS Step Functions workflow, but only for orders with a status of PAID, and each order must first be enriched with customer details from an internal API. The team wants to write as little code as possible.',
      opts: [_o('Create an Amazon EventBridge rule on the default event bus that matches DynamoDB stream records with status PAID and targets the workflow.', 0, 'DynamoDB stream records do not arrive on the default bus; rules do not read streams — Pipes do.'),
        _o('Write an AWS Lambda function on the table’s DynamoDB stream that filters PAID orders, calls the API, and starts the workflow.', 0, 'It works, but it is exactly the code the team wants to avoid.'),
        _o('Create an Amazon EventBridge pipe with the table’s DynamoDB stream as source, a PAID filter, an API enrichment and the workflow.', 1, 'Pipes connect a stream source to one target with a filter and an enrichment step, no code.'),
        _o('Turn on Kinesis Data Streams for DynamoDB, and deliver the records through Amazon Data Firehose to the Step Functions workflow.', 0, 'Firehose delivers to storage and analytics destinations; Step Functions is not one of them.')],
      stub: { pat: 'event routing', del: 'none stated', lat: 'any', sup: 'least ops' }, words: ['only for orders with a status of PAID', 'enriched with customer details', 'as little code as possible'],
      expl: 'One source → filter → enrich → one target, no code = **EventBridge Pipes**. A Lambda poller is the code version; rules match events on a bus, not records in a stream.' },

    /* ---------------- Kinesis / MSK / MQ ---------------- */
    { id: 'E15', src: 'New', line: 'stream',
      q: 'A payment processor sends card transactions to AWS. A fraud-scoring application and a real-time dashboard must both read every transaction, in order for each card, within a second. The fraud team must also be able to reprocess the last 3 days of transactions after a model change.',
      opts: [_o('Write the transactions to an Amazon SQS FIFO queue with the card ID as the message group ID, read by both of the applications.', 0, 'Each message goes to one consumer and is deleted — no second reader and no replay.'),
        _o('Write the transactions to an Amazon Data Firehose stream that delivers to Amazon S3, and have both applications read from S3.', 0, 'Buffered delivery to files: no per-card ordered stream to read within a second.'),
        _o('Write the transactions to an Amazon SNS FIFO topic with the card ID as the message group ID, subscribed to by both of the applications.', 0, 'SNS FIFO delivers only to SQS queues, so neither application can subscribe directly, and no archive is set up to replay from.'),
        _o('Write the transactions to a Kinesis data stream with the card ID as the partition key and a retention period of at least 3 days.', 1, 'Every consumer reads every record, in order per key, in real time — and can replay within retention.')],
      stub: { pat: 'stream', del: 'replay', lat: 'real time', sup: 'none stated' }, words: ['must both read every transaction', 'in order for each card', 'within a second', 'reprocess the last 3 days'],
      expl: 'Two readers of every record + order per key + real time + replay = **Kinesis Data Streams** with retention ≥ 3 days. Queues and standard SNS topics hand messages on and forget them; an SNS FIFO topic can replay only from an opt-in archive, and only to SQS queues.' },
    { id: 'E16', src: 'New', line: 'stream',
      q: 'Producers write 5,000 records per second, each about 2 KB, to a Kinesis data stream in provisioned mode with 4 shards. The partition keys are well distributed, but the producers receive ProvisionedThroughputExceededException errors. What is the smallest change that stops the throttling?',
      opts: [_o('Increase the stream to at least 5 shards, because each shard accepts 1,000 records per second and the stream receives 5,000.', 0, 'The record count fits 5 shards, but 5,000 × 2 KB = 10 MB/s needs 10 shards at 1 MB/s each.'),
        _o('Increase the stream to at least 10 shards, because each shard accepts 1 MB/s or 1,000 records per second of writes.', 1, '10 MB/s of data ÷ 1 MB/s per shard = 10 shards; the binding limit is data, not records.'),
        _o('Register the consumers for enhanced fan-out, because each consumer then gets its own 2 MB/s of throughput per shard.', 0, 'Enhanced fan-out is a read feature; the producers are throttled on writes.'),
        _o('Raise the retention period to 7 days, because records kept longer are written to the stream at a lower priority.', 0, 'Retention has nothing to do with write throughput.')],
      stub: { pat: 'stream', del: 'none stated', lat: 'any', sup: 'none stated' }, words: ['5,000 records per second', 'about 2 KB', '4 shards', 'ProvisionedThroughputExceededException'],
      expl: 'Shard math: **1 MB/s or 1,000 records/s** per shard for writes, whichever is hit first. 5,000 × 2 KB = **10 MB/s → 10 shards**. Enhanced fan-out and retention do not touch writes.' },
    { id: 'E17', src: 'New', line: 'stream',
      q: 'Five applications read the same Kinesis data stream with the GetRecords API. As consumers were added, read latency rose and the applications now get read throttling errors, while producers write without errors. Each application must get dedicated read throughput with the LEAST change to the producers.',
      opts: [_o('Register each application as an enhanced fan-out consumer, so that each one receives its own 2 MB/s per shard over HTTP/2.', 1, 'Dedicated 2 MB/s per shard per consumer, pushed — exactly the stated need, with no producer change.'),
        _o('Double the number of shards, so that the shared 2 MB/s of read throughput per shard is spread across twice as many shards.', 0, 'More shared capacity, still shared — not dedicated per application, and every producer’s keys are rehashed.'),
        _o('Change every producer to use a random partition key, so that the reads are spread more evenly across all of the shards.', 0, 'It changes the producers, breaks per-key order and still leaves the five readers sharing each shard.'),
        _o('Move the five applications to Amazon Data Firehose, so that each one reads its own copy of the stream from the buffer.', 0, 'Firehose has no consumers to read from; it only delivers to destinations.')],
      stub: { pat: 'stream', del: 'none stated', lat: 'real time', sup: 'least ops' }, words: ['Five applications read the same Kinesis data stream', 'producers write without errors', 'dedicated read throughput'],
      expl: 'Shared consumers split **2 MB/s per shard**. **Enhanced fan-out** gives each registered consumer its own 2 MB/s per shard, pushed with about 70 ms latency.' },
    { id: 'E18', src: 'New', line: 'firehose',
      q: 'JSON events arrive in an Amazon Data Firehose stream and are delivered to Amazon S3. Analysts query them with Amazon Athena, and query costs are high because every query scans whole JSON files. The company wants Parquet files in S3 with the LEAST operational overhead.',
      opts: [_o('Add an AWS Lambda transformation to the Firehose stream that rewrites every batch of JSON records into a Parquet file.', 0, 'Code to write and maintain for something Firehose does as a setting.'),
        _o('Run a nightly Amazon EMR cluster that converts the previous day’s JSON files to Parquet and deletes the JSON originals.', 0, 'A cluster to run every night — more operations than a stream setting.'),
        _o('Enable record format conversion on the Firehose stream, with the table schema from the AWS Glue Data Catalog, to write Parquet.', 1, 'Built in: Firehose converts JSON to Parquet or ORC using a Data Catalog schema before delivery.'),
        _o('Change the Firehose destination to Amazon OpenSearch Service, and let the analysts query the data there instead of in Amazon Athena.', 0, 'A different engine and no Parquet in S3 — not what was asked.')],
      stub: { pat: 'stream', del: 'none stated', lat: 'near real time', sup: 'least ops' }, words: ['every query scans whole JSON files', 'Parquet files in S3', 'LEAST operational overhead'],
      expl: 'Firehose **record format conversion** (JSON → Parquet/ORC with a Glue Data Catalog schema) is a setting. Lambda transforms and EMR jobs do the same with code or clusters.' },
    { id: 'E19', src: 'New', line: 'stream',
      q: 'A company must detect anomalies in IoT sensor readings from a Kinesis data stream within seconds, using SQL-like windowed aggregations. The application is a new design built in 2026. Which service should process the stream?',
      opts: [_o('Amazon Kinesis Data Analytics for SQL, with a SQL application that reads the stream and runs the windowed aggregations.', 0, 'Kinesis Data Analytics for SQL took no new applications from 15 Oct 2025, and its applications were deleted from 27 Jan 2026.'),
        _o('Amazon Data Firehose with a buffer of 900 seconds, delivering the readings to Amazon S3 for Amazon Athena to aggregate.', 0, 'Fifteen minutes of buffering and batch queries — not within seconds.'),
        _o('AWS Glue with a scheduled ETL job that reads the stream every hour and writes the aggregated readings to Amazon S3.', 0, 'An hourly batch — not within seconds.'),
        _o('Amazon Managed Service for Apache Flink, with an application that reads the stream and runs the windowed aggregations.', 1, 'Real-time stream processing with windows over a Kinesis stream — the service AWS points to today.')],
      stub: { pat: 'stream', del: 'none stated', lat: 'real time', sup: 'none stated' }, words: ['within seconds', 'windowed aggregations', 'new design built in 2026'],
      expl: 'Real-time windowed processing of a stream = **Managed Service for Apache Flink**. Older banks answer **Kinesis Data Analytics** — its SQL applications no longer exist. Exam-day rule: if an option says only “Kinesis Data Analytics” and no Flink option is offered, pick it — the Flink flavour was renamed **Managed Service for Apache Flink**.', update: 'Kinesis Data Analytics for SQL: no new applications from 15 Oct 2025; existing applications deleted from 27 Jan 2026.' },
    { id: 'E20', src: 'New', line: 'stream',
      q: 'A company is migrating an on-premises order system whose Java services exchange messages over JMS through an Apache ActiveMQ broker. The company wants a managed broker on AWS and must keep code changes to a minimum.',
      opts: [_o('Amazon SQS, replacing the JMS producers and consumers with SQS SDK calls and one SQS standard queue for each JMS queue.', 0, 'A rewrite of every producer and consumer.'),
        _o('Amazon MQ for ActiveMQ, pointing the existing JMS clients at the new broker’s endpoint after migrating the queues.', 1, 'A managed ActiveMQ broker: the JMS code stays, only the endpoint changes.'),
        _o('Amazon MSK Serverless, replacing the JMS clients with Kafka producers and consumers and one topic per JMS queue.', 0, 'Kafka is a different protocol — a rewrite.'),
        _o('Apache ActiveMQ on Amazon EC2 instances in two AZs, with the existing JMS clients pointed at the new instances.', 0, 'No code change, but not managed: you patch, scale and fail over the broker yourself.')],
      stub: { pat: 'queue', del: 'none stated', lat: 'any', sup: 'least ops' }, words: ['over JMS through an Apache ActiveMQ broker', 'managed broker', 'code changes to a minimum'],
      expl: 'Existing broker protocol (JMS, ActiveMQ) + managed + minimal change = **Amazon MQ**. SQS and MSK are rewrites; EC2 is not managed.' },

    /* ---------------- Lambda / API Gateway ---------------- */
    { id: 'E21', src: 'New', line: 'lambda',
      q: 'An AWS Lambda function is invoked asynchronously by Amazon S3 for every uploaded invoice. Some invoices fail validation, and after the built-in retries those events are lost. The team must keep every failed event together with its error message and stack trace for later reprocessing, with the LEAST operational overhead.',
      opts: [_o('Configure an on-failure destination on the function that sends the invocation record to an Amazon SQS queue for reprocessing.', 1, 'Destinations receive the event plus the response details — error message and stack trace — with no code.'),
        _o('Configure a dead-letter queue on the function that sends the original event to an Amazon SQS queue for later reprocessing.', 0, 'A DLQ keeps only the original event, not the error message and stack trace the team needs.'),
        _o('Raise the function’s maximum retry attempts for asynchronous invocations to 10, so that failing invoices get more attempts.', 0, 'Async retries can be set from 0 to 2 only — and a validation failure fails again anyway.'),
        _o('Wrap the handler in code that catches every error and writes the event, its message and stack trace to an Amazon DynamoDB table.', 0, 'It works, but it is code to write and keep correct — a destination does it as configuration.')],
      stub: { pat: 'any', del: 'none stated', lat: 'any', sup: 'least ops' }, words: ['invoked asynchronously', 'error message and stack trace', 'LEAST operational overhead'],
      expl: 'Async failures: Lambda retries **twice**, keeps the event up to **6 hours**, then discards it. An **on-failure destination** keeps the invocation record with the error details; a DLQ keeps only the event.' },
    { id: 'E22', src: 'New', line: 'lambda',
      q: 'A company exposes a product API to partners through Amazon API Gateway and AWS Lambda. Each partner must use its own API key with a monthly quota, responses for popular products must be cached, and requests must be inspected by AWS WAF. The company wants the MOST cost-effective API type that meets every requirement.',
      opts: [_o('An HTTP API with a JWT authorizer per partner, a usage plan for each API key, and AWS WAF attached to the API stage.', 0, 'HTTP APIs are cheaper but have no API keys, usage plans, caching or AWS WAF integration.'),
        _o('A WebSocket API with one route per partner, a usage plan for each API key, and AWS WAF attached to the API stage.', 0, 'WebSocket APIs are built for persistent two-way connections, not cached request-response calls.'),
        _o('A REST API with usage plans and API keys per partner, stage caching for the product resource, and AWS WAF on the stage.', 1, 'API keys, usage plans, caching and AWS WAF are REST API features — the cheapest type that has all of them.'),
        _o('An Application Load Balancer with AWS WAF in front of the Lambda functions, and per-partner quotas kept in an Amazon DynamoDB table.', 0, 'No API keys, quotas or response cache: you would build them yourself.')],
      stub: { pat: 'any', del: 'none stated', lat: 'any', sup: 'cheapest' }, words: ['its own API key with a monthly quota', 'must be cached', 'inspected by AWS WAF', 'MOST cost-effective'],
      expl: '**REST API** = API keys, usage plans, per-client throttling, caching, request validation, WAF, private endpoints. **HTTP API** is cheaper only when none of those is required.' },
    { id: 'E23', src: 'New', line: 'lambda',
      q: 'An AWS Lambda function processes an Amazon SQS standard queue with a batch size of 10. When one message in a batch fails, all 10 messages return to the queue and the 9 successful ones are processed again. The team wants to stop reprocessing successful messages without lowering throughput.',
      opts: [_o('Turn on ReportBatchItemFailures in the event source mapping, and return only the IDs of the failed messages from the function.', 1, 'Partial batch responses: only the failed messages become visible again; the batch size stays.'),
        _o('Set the event source mapping’s batch size to 1, so that a failed message never causes other messages to be processed again.', 0, 'It works, but ten times the invocations — the stem forbids lowering throughput.'),
        _o('Increase the queue’s visibility timeout to 12 hours, so that failed batches wait much longer before they become visible to the function again.', 0, 'The whole batch still comes back — only later.'),
        _o('Add a dead-letter queue with a maxReceiveCount of 1, so that every message in a failed batch moves straight to that queue.', 0, 'The 9 good messages would land in the DLQ with the bad one.')],
      stub: { pat: 'queue', del: 'none stated', lat: 'any', sup: 'none stated' }, words: ['all 10 messages return to the queue', 'stop reprocessing successful messages', 'without lowering throughput'],
      expl: 'By default a failed batch returns whole. **`ReportBatchItemFailures`** lets the function name the failed messages; only they are retried.' },
    { id: 'E24', src: 'New', line: 'lambda',
      q: 'A Java AWS Lambda function behind Amazon API Gateway serves an interactive web application. Users see slow responses on the first requests after traffic rises each morning. Traffic is predictable during business hours, and responses must be consistently fast. Which configuration meets the requirement?',
      opts: [_o('Turn on Lambda SnapStart and also configure provisioned concurrency on the same published version for business hours.', 0, 'SnapStart cannot be combined with provisioned concurrency.'),
        _o('Set reserved concurrency on the function equal to the business-hours peak, so that its execution environments stay ready.', 0, 'Reserved concurrency caps and guarantees concurrency; it does not initialise environments in advance.'),
        _o('Raise the function’s memory to 10,240 MB, so that every new execution environment starts with the most CPU available.', 0, 'More CPU can shorten initialisation, but every new environment still cold-starts — not consistently fast.'),
        _o('Configure provisioned concurrency on a published version or alias, sized to the expected business-hours load.', 1, 'Pre-initialised environments answer at once, which is what provisioned concurrency is for; it is charged while configured.')],
      stub: { pat: 'any', del: 'none stated', lat: 'real time', sup: 'fastest' }, words: ['slow responses on the first requests', 'predictable during business hours', 'consistently fast'],
      expl: 'Cold starts on an interactive, predictable load = **provisioned concurrency**. Reserved concurrency is a cap; SnapStart is an alternative for Java, but never together with provisioned concurrency.' },

    /* ---------------- Step Functions ---------------- */
    { id: 'E25', src: 'New', line: 'sfn',
      q: 'An IoT platform receives about 20,000 device events per second. Each event runs a short workflow of three AWS Lambda steps that finishes in under 10 seconds, and every step is idempotent. The company wants the MOST cost-effective orchestration.',
      opts: [_o('An AWS Step Functions Standard workflow for each event, with Retry on every step and the full execution history kept for audits.', 0, 'Standard is priced per state transition; at 20,000 events per second Express costs far less, and no audit history was asked for.'),
        _o('An AWS Step Functions Express workflow for each event, with Retry on every step, started asynchronously by the ingestion API.', 1, 'Built for high-volume, short workflows; priced by executions and duration; at-least-once suits idempotent steps.'),
        _o('An Amazon SWF workflow for each event, with a decider and activity workers on EC2 instances that poll for the three steps.', 0, 'Servers and polling for a short, high-volume job — the legacy service and the most to run.'),
        _o('An AWS Step Functions Standard workflow that pauses on a .waitForTaskToken task for each of the three Lambda steps.', 0, 'Still per-transition pricing, and callbacks add waiting that no step needs.')],
      stub: { pat: 'workflow', del: 'at least once', lat: 'any', sup: 'cheapest' }, words: ['20,000 device events per second', 'under 10 seconds', 'idempotent', 'MOST cost-effective'],
      expl: 'High volume + under 5 minutes + idempotent + cheapest = **Express** (priced per execution and duration). Standard is for long, exactly-once, auditable work. At 20,000 starts per second, request a raise of the Express `StartExecution` rate first: it is a soft quota of 6,000 per second by default.' },
    { id: 'E26', src: 'New', line: 'sfn',
      q: 'A company must run an image-labelling AWS Lambda function on 8 million images stored in Amazon S3, as fast as possible and without managing servers. Failed items must be retried, and the run must report which images failed.',
      opts: [_o('An AWS Step Functions Standard workflow with a Distributed Map state that reads the S3 objects and runs child workflows in parallel.', 1, 'Distributed Map reads items from S3 and runs up to 10,000 child workflows in parallel, with retries and a failure report.'),
        _o('An AWS Step Functions Express workflow with a Distributed Map state that reads the S3 objects and runs child workflows in parallel.', 0, 'Distributed Map is not available in Express workflows.'),
        _o('An AWS Step Functions Standard workflow with an inline Map state that iterates over all 8 million keys inside one execution.', 0, 'An inline Map runs inside one execution and its 25,000-event history — millions of items do not fit.'),
        _o('A script on an Amazon EC2 instance that lists the whole bucket and invokes the function for each object, logging failures to a local file.', 0, 'A server to run, and the parallelism, retries and failure report are yours to build.')],
      stub: { pat: 'workflow', del: 'none stated', lat: 'batch', sup: 'fastest' }, words: ['8 million images stored in Amazon S3', 'as fast as possible', 'without managing servers'],
      expl: 'Millions of S3 items in parallel, serverless = **Distributed Map** (Standard workflows only, up to 10,000 parallel child executions). Inline Map is bounded by one execution’s history.' },

    /* ---------------- Glue / Athena / Lake Formation ---------------- */
    { id: 'E27', src: 'New', line: 'etl',
      q: 'New clickstream data lands in Amazon S3 every hour under year/month/day/hour prefixes, and new columns are sometimes added. Analysts query it with Amazon Athena and must see new partitions and columns without anyone running DDL. The solution must need the LEAST operational overhead.',
      opts: [_o('Have a data engineer run ALTER TABLE ADD PARTITION and ADD COLUMNS statements in Athena whenever new data or columns arrive.', 0, 'Manual DDL — the stem rules it out.'),
        _o('Run a long-running Amazon EMR cluster with its own Hive metastore that discovers new partitions and columns for Athena.', 0, 'A cluster running all the time just to keep a catalog — far more to operate than a crawler.'),
        _o('Schedule an AWS Glue crawler on the S3 prefix every hour, so that it adds new partitions and columns to the Data Catalog table.', 1, 'Crawlers infer schema changes and partitions into the Data Catalog that Athena reads.'),
        _o('Register the S3 prefix in AWS Lake Formation, and grant the analysts column-level permissions on the table and on all of its partitions.', 0, 'Governance, not schema discovery — new partitions and columns would still be missing.')],
      stub: { pat: 'ETL', del: 'none stated', lat: 'batch', sup: 'least ops' }, words: ['new columns are sometimes added', 'without anyone running DDL', 'LEAST operational overhead'],
      expl: 'Schema and partition discovery = **Glue crawler** → **Data Catalog** (shared by Athena, EMR, Redshift Spectrum).' },
    { id: 'E28', src: 'New', line: 'query',
      q: 'A company runs Amazon Athena queries over 50 TB of uncompressed CSV log files in Amazon S3. Most queries filter on the event date and read 3 of the 40 columns. The company wants to reduce the cost of these queries the MOST. Which TWO actions should the company take? (Select TWO.)',
      opts: [_o('Move the log files to the S3 Standard-Infrequent Access storage class, so that each byte that Athena scans costs less.', 0, 'Athena charges per byte scanned; the storage class does not change how much a query scans.'),
        _o('Convert the files to Apache Parquet with compression, so that each query reads only the 3 columns it needs from smaller files.', 1, 'Columnar + compressed: a query reads 3 of 40 columns from far fewer bytes.'),
        _o('Create a separate Athena workgroup for the analysts, so that their queries run on dedicated capacity at a lower price.', 0, 'Workgroups separate teams and can cap scanning; they do not lower the price per TB.'),
        _o('Partition the data by event date in the S3 prefixes, so that queries that filter on the date skip every other partition.', 1, 'Partition pruning: a date filter reads only the matching prefixes.'),
        _o('Load the logs into Amazon Redshift every night, and point the analysts at the warehouse instead of the files in S3.', 0, 'A warehouse to run and pay for, not a cheaper Athena query.')],
      stub: { pat: 'ad hoc query', del: 'none stated', lat: 'batch', sup: 'cheapest' }, words: ['uncompressed CSV', 'filter on the event date', '3 of the 40 columns', 'Select TWO'],
      expl: 'Athena bills **bytes scanned**. **Columnar + compression** cut the bytes per row; **partitions** cut the rows. Together AWS quotes 30–90% savings.' },
    { id: 'E29', src: 'New', line: 'query',
      q: 'A company’s data lake in Amazon S3 is catalogued in AWS Glue. Marketing analysts query the customer table with Amazon Athena. They must see only the rows for their own region and must never see the email column, while the data team sees everything. Access must be managed centrally on the one table.',
      opts: [_o('Use AWS Lake Formation to grant the analysts the table without the email column, plus a data filter limiting rows to their region.', 1, 'Column permissions and row-level data filters on the catalog table, enforced by Athena, managed in one place.'),
        _o('Write an S3 bucket policy that denies the analysts’ role access to the email column and to other regions’ rows in the objects.', 0, 'S3 policies act on objects and prefixes, not on columns or rows inside a file.'),
        _o('Run an AWS Glue job every night that copies the table without the email column into a separate S3 prefix per region for the analysts.', 0, 'Copies to keep in sync and secure — not central control of the one table.'),
        _o('Encrypt the email column with a separate AWS KMS key, deny the analysts kms:Decrypt, and let them query the same table.', 0, 'S3 encryption keys apply to whole objects, not to one column inside them.')],
      stub: { pat: 'ad hoc query', del: 'none stated', lat: 'any', sup: 'none stated' }, words: ['only the rows for their own region', 'never see the email column', 'managed centrally on the one table'],
      expl: 'Columns, rows and cells on a data-lake table = **Lake Formation** (column grants + data filters). S3, IAM and KMS stop at the object.' },
    { id: 'E30', src: 'New', line: 'etl',
      q: 'A company receives new JSON files in an Amazon S3 bucket throughout the day. Every night it must transform only the files that arrived since the last run and write them as Parquet for analytics. The company has no servers and wants the LEAST operational overhead. Which TWO actions should the company take? (Select TWO.)',
      opts: [_o('Create an AWS Glue ETL job that writes Parquet output to Amazon S3, and start it every night from a scheduled Glue trigger.', 1, 'Serverless Spark ETL on a schedule — nothing to run between jobs.'),
        _o('Create an AWS Data Pipeline with a nightly schedule that runs a transformation script on an EC2 resource that it launches.', 0, 'Data Pipeline is closed to new customers, and the EC2 resource is a server to manage.'),
        _o('Enable job bookmarks on the AWS Glue job, so that each nightly run reads only the files added since the last successful run.', 1, 'Bookmarks track what was processed: only new files are read.'),
        _o('Launch an Amazon EMR cluster every night that lists the bucket, compares it with a manifest file, and converts the new files.', 0, 'A cluster plus manifest code to maintain — more operations than Glue with bookmarks.'),
        _o('Configure an AWS Lambda function on every S3 upload that converts each file at once, and drop the nightly run altogether.', 0, 'The stem asks for a nightly run; per-upload conversion also writes many small Parquet files.')],
      stub: { pat: 'ETL', del: 'none stated', lat: 'batch', sup: 'least ops' }, words: ['only the files that arrived since the last run', 'no servers', 'LEAST operational overhead', 'Select TWO'],
      expl: 'Least ops ETL = **Glue job** on a schedule; “only new files” = **job bookmarks**. EMR and Data Pipeline add servers or a closed service.' }
  ];
})();
